import type { ImperativeHandleMetadata } from "../../types";
import { Box } from "../Box";
import { DocsSection } from "../DocsSection";
import { Header } from "../Header";
import { ImperativeHandleMethod } from "./ImperativeHandleMethod";

/**
 * Documentation for an imperative API (e.g. the methods available through a ref),
 * generated by `compileDocs` from an interface's TSDoc comments.
 */
export function ImperativeHandle({
  json,
  section
}: {
  /** JSON generated by `compileDocs` (e.g. `public/generated/docs/ListImperativeAPI.json`) */
  json: ImperativeHandleMetadata;
  /** Label shown above the page title */
  section: string;
}) {
  return (
    <Box direction="column" gap={4}>
      <Header
        section={section}
        sourceCodePath={json.filePath}
        title={`${json.name}`}
      />
      <DocsSection sections={json.description} />
      <Box direction="column">
        <dl className="flex flex-col">
          {json.methods.map((method, index) => (
            <ImperativeHandleMethod key={index} method={method} />
          ))}
        </dl>
      </Box>
    </Box>
  );
}
